<script setup lang="ts">
import {ref,computed} from 'vue';import {useApp} from '../stores/app';import Icon from '../components/Icon.vue';
const app=useApp(),name=ref(''),category=ref('Breakfast'),calories=ref<number|undefined>(),protein=ref<number|undefined>(),carbs=ref<number|undefined>(),fat=ref<number|undefined>(),message=ref(''),busy=ref(false),day=ref(app.today);
const meals=computed(()=>app.data.meals.filter(m=>m.day===day.value));const totals=computed(()=>meals.value.reduce((a,m)=>({calories:a.calories+m.calories,protein:a.protein+m.protein,carbs:a.carbs+m.carbs,fat:a.fat+m.fat}),{calories:0,protein:0,carbs:0,fat:0}));
async function add(){if(busy.value)return;busy.value=true;try{if(!name.value.trim())return;await app.addMeal({name:name.value.trim(),category:category.value,calories:calories.value||0,protein:protein.value||0,carbs:carbs.value||0,fat:fat.value||0});name.value='';calories.value=protein.value=carbs.value=fat.value=undefined;day.value=app.today;message.value='Meal saved on this device.';}catch{message.value='Unable to save. Check the storage message above.';}finally{busy.value=false;}}
async function remove(id:string){app.data.meals=app.data.meals.filter(m=>m.id!==id);await app.save().catch(()=>{});}
function copy(id:string){const m=app.data.meals.find(x=>x.id===id)!;name.value=m.name;category.value=m.category;calories.value=m.calories;protein.value=m.protein;carbs.value=m.carbs;fat.value=m.fat;}
</script>
<template><section class="page-heading"><div><div class="eyebrow">FUEL YOUR PROGRESS</div><h1>A stronger you <span>starts here.</span></h1><p>Log what you eat. Learn what supports your training.</p></div><label class="date-filter">View day<input v-model="day" type="date" :max="app.today"></label></section><div class="four-stats"><section class="card stat-card" v-for="(value,key) in totals" :key="key"><span class="stat-top">{{key}}</span><strong>{{Math.round(value)}}<small>{{key==='calories'?'kcal':'g'}}</small></strong></section></div><div class="two-columns"><section class="card"><div class="section-title"><h3>Log a meal</h3><Icon name="Utensils"/></div><p class="muted">Use your food label or a trusted nutrition source. Restaurant portions are estimates.</p><form @submit.prevent="add" class="form-grid"><label class="span-2">Food or meal name<input v-model="name" maxlength="100" placeholder="e.g. Rice, grilled chicken & vegetables" required></label><label class="span-2">Meal<select v-model="category"><option>Breakfast</option><option>Lunch</option><option>Dinner</option><option>Snack</option></select></label><label>Calories (kcal)<input v-model.number="calories" type="number" min="0" max="10000" step="1" required placeholder="0"></label><label>Protein (g)<input v-model.number="protein" type="number" min="0" max="1000" step="0.1" required placeholder="0"></label><label>Carbs (g)<input v-model.number="carbs" type="number" min="0" max="2000" step="0.1" required placeholder="0"></label><label>Fat (g)<input v-model.number="fat" type="number" min="0" max="1000" step="0.1" required placeholder="0"></label><button class="button primary span-2" :disabled="busy"><Icon name="Plus"/>Add to today’s log</button></form><p v-if="message" role="status" class="lime-text">{{message}}</p><p class="fine muted">Enter totals for the portion you ate. No automatic food recognition or bundled food database in this foundation release.</p></section><section class="card"><div class="section-title"><h3>Meal journal</h3><span class="pill">{{meals.length}} entries</span></div><div v-if="!meals.length" class="empty"><Icon name="Utensils" :size="36"/><h3>A fresh plate.</h3><p>No meals logged for this day yet.</p></div><article v-for="meal in meals" :key="meal.id" class="meal-row"><span class="meal-icon"><Icon name="Utensils"/></span><div><small class="eyebrow">{{meal.category}}</small><h4>{{meal.name}}</h4><small>{{meal.protein}} g protein · {{meal.carbs}} g carbs · {{meal.fat}} g fat</small><button class="text-link" @click="copy(meal.id)">Use again</button></div><strong>{{meal.calories}}<small> kcal</small></strong><button class="icon-button" aria-label="Delete meal" @click="remove(meal.id)"><Icon name="Trash2" :size="16"/></button></article><div class="callout"><strong>Your targets, your choice.</strong><p>Set optional calorie and protein targets in your profile. This release does not prescribe a diet.</p><RouterLink class="text-link" to="/settings">Edit targets <Icon name="ArrowRight" :size="16"/></RouterLink></div></section></div></template>
